// Survey data generated by studio/design/assets/contours.mjs (copied verbatim).
import raw from "@/assets/contours-data.json";

export type Spot = { code: string; t: number; T: number; left: number; top: number };
export type Crossing = { t: number; T: number; index: boolean; left: number };
export type ProfileEvent = { code: string; t: number; time: string; T: number; left: number; top: number };
export type Phase = { id: string; from: number; to: number; duration: string; pct: number | null };
export type Mini = {
  batch: number;
  origin: string;
  file: string;
  drop: { t: number; T: number; left: number; top: number };
  fc: { t: number; T: number };
  dtr: number;
};

export const data = raw as unknown as {
  hero: {
    sectionLine: { A: { left: number; top: number }; A2: { left: number; top: number } };
    spots: Spot[];
    clearing: { left: number; top: number };
  };
  strip: { crossings: Crossing[] };
  profile: {
    gridlines: number[];
    events: ProfileEvent[];
    phases: Phase[];
    btPerSecond: number[];
  };
  minis: Mini[];
};

/** Profile/strip/minis share one domain: x = t / 720 s, y = (220 − T) / 160. */
export const T_END = 720;
export const xPct = (t: number) => (t / T_END) * 100;
export const yPct = (T: number) => ((220 - T) / 160) * 100;

export const mmss = (s: number) => `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, "0")}`;
